ventas-ecommerce.filter_code:
filter {
  json { source => "message" }
  date { match => ["order_date", "ISO8601"] target => "@timestamp" }
  mutate { remove_field => ["message"] }
}

encuentros-clinicos.filter_code:
filter {
  csv {
    source => "message"
    columns => ["ts","class","code","desc","patient","city","cost","claim","covered","reason","triage"]
  }
  date { match => ["ts", "ISO8601"] target => "@timestamp" }
  mutate { convert => { "cost" => "float" "claim" => "float" "covered" => "float" } }
  if [triage] == "" { mutate { remove_field => ["triage"] } }
  if [reason] == "" { mutate { remove_field => ["reason"] } }
  mutate { remove_field => ["message", "ts"] }
}

cts.filter_code:
filter {
  json { source => "message" target => "trace" }
  if [trace][0] {
    split { field => "trace" }
  }
  ruby { code => "t = event.remove('trace'); if t.is_a?(Hash); t.each { |k, v| event.set(k, v) }; end" }
  json { source => "user" target => "user" }
  date { match => ["record_time", "UNIX_MS"] target => "@timestamp" }
  mutate { remove_field => ["message"] }
}
